    public static double get(double distance) {
        double d = distance - DIST_MIN;
        int n = TIME_LUT.length;

        if (d <= 0) return TIME_LUT[0];
        if (d >= (n - 1) * STEP) return TIME_LUT[n - 1];

        int i = (int)Math.floor(d / STEP);
        double t = (d - i * STEP) / STEP;

        return TIME_LUT[i] + t * (TIME_LUT[i + 1] - TIME_LUT[i]);
    }

    private ShotTime() {}
